export default {
  async fetch(request, env, ctx) {
    const cached = await getCachedResponse(request);
    ctx.waitUntil(logAnalytics(request));
    return cached ?? fetch(request);
  }
};

async function getCachedResponse(request) {
  return globalThis.__lastResponse; // captured from a previous request's closure
}

// throws: Cannot perform I/O on behalf of a different request. I/O objects (such as bodies) from a request are valid only within that same request.

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

app.get("/orders", async (req, res) => {
  const client = await pool.connect();
  const result = await client.query("SELECT * FROM orders WHERE user_id = $1", [req.user.id]);
  res.json(result.rows);
  // client.release() is never called
});

